  const handleSwitchOutlet = async (targetId) => {
     if (!targetId) {
        localStorage.removeItem('pos_active_outlet_id');
        setActiveOutletId(null);
     } else {
        localStorage.setItem('pos_active_outlet_id', String(targetId));
        setActiveOutletId(targetId);
     }
     toast.info("Switching outlet context and synchronizing database caches...");
     try {
        await initApp();
        toast.success("Outlet synchronized successfully!");
     } catch (err) {
        console.error("Failed to synchronize active outlet app state:", err);
        toast.error("Failed to synchronize active outlet.");
     }
  };

